  (AVG(?gorgonStr) AS ?Gorgon_Str_Mean),
  (AVG(?dhampirDex) AS ?Dhampir_Dex_Mean),
  (AVG(?gorgonDex) AS ?Gorgon_Dex_Mean),
  (AVG(?dhampirCon) AS ?Dhampir_Con_Mean),
  (AVG(?gorgonCon) AS ?Gorgon_Con_Mean),
  (AVG(?dhampirInt) AS ?Dhampir_Int_Mean),
  (AVG(?gorgonInt) AS ?Gorgon_Int_Mean),
  (AVG(?dhampirWis) AS ?Dhampir_Wis_Mean),
  (AVG(?gorgonWis) AS ?Gorgon_Wis_Mean),
  (AVG(?dhampirCha) AS ?Dhampir_Cha_Mean),
