PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?beastName (SUM(?value) / COUNT(?value)) AS ?meanDefense
WHERE {
  { 
    ?beast a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
           <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasName> ?beastName .
    FILTER (?beastName = "Centaur" || ?beastName = "Medusa")

    ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasACValue> ?ac .
    BIND(?ac AS ?value)
  }
  UNION
  { 
    ?beast a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
           <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasName> ?beastName .
    FILTER (?beastName = "Centaur" || ?beastName = "Medusa")

    ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasFortValue> ?fort .
    BIND(?fort AS ?value)
  }
  UNION
  { 
    ?beast a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
           <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasName> ?beastName .
    FILTER (?beastName = "Centaur" || ?beastName = "Medusa")

    ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasRefValue> ?ref .
    BIND(?ref AS ?value)
  }
  UNION
  { 
    ?beast a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
           <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasName> ?beastName .
    FILTER (?beastName = "Centaur" || ?beastName = "Medusa")

    ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasWillValue> ?will .
    BIND(?will AS ?value)
  }
}
GROUP BY ?beastName

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?satyrMean ?cacodaemonMean
WHERE {
  # Satyr's attributes and sum calculation
  <Satyr> a Beast;
          atk ?s_atk;
          hasXPValue ?s_xp;
          hasCRValue ?s_cr;
          hasWillValue ?s_will;
          wis ?s_wis;
          hasTouchValue ?s_touch;
          con ?s_con;
          str ?s_str;
          hasRefValue ?s_ref;
          cmd ?s_cmd;
          hasHPValue ?s_hp;
          int ?s_int;
          cmb ?s_cmb;
          hasLevel ?s_level;
          hasInitValue ?s_init;
          hasACValue ?s_ac;
          dex ?s_dex;
          cha ?s_cha;
          hasSpeedValue ?s_speed;
          hasFortValue ?s_fort.

  # Calculate Satyr's total sum
  BIND( ?s_atk + ?s_xp + ?s_cr + ?s_will + ?s_wis + ?s_touch + ?s_con + ?s_str + ?s_ref + ?s_cmd + ?s_hp + ?s_int + ?s_cmb + ?s_level + ?s_init + ?s_ac + ?s_dex + ?s_cha + ?s_speed + ?s_fort AS ?satyrSum )

  # Calculate Satyr's mean
  BIND( ?satyrSum / 20 AS ?satyrMean )

  # Cacodaemon's attributes and sum calculation
  <Cacodaemon> a Beast;
               atk ?c_atk;
               hasXPValue ?c_xp;
               hasCRValue ?c_cr;
               hasWillValue ?c_will;
               wis ?c_wis;
               hasTouchValue ?c_touch;
               con ?c_con;
               str ?c_str;
               hasRefValue ?c_ref;
               cmd ?c_cmd;
               hasHPValue ?c_hp;
               int ?c_int;
               cmb ?c_cmb;
               hasLevel ?c_level;
               hasInitValue ?c_init;
               hasACValue ?c_ac;
               dex ?c_dex;
               cha ?c_cha;
               hasSpeedValue ?c_speed;
               hasFortValue ?c_fort.

  # Calculate Cacodaemon's total sum
  BIND( ?c_atk + ?c_xp + ?c_cr + ?c_will + ?c_wis + ?c_touch + ?c_con + ?c_str + ?c_ref + ?c_cmd + ?c_hp + ?c_int + ?c_cmb + ?c_level + ?c_init + ?c_ac + ?c_dex + ?c_cha + ?c_speed + ?c_fort AS ?cacodaemonSum )

  # Calculate Cacodaemon's mean
  BIND( ?cacodaemonSum / 20 AS ?cacodaemonMean )

  # Check if Satyr's mean is greater than Cacodaemon's
  FILTER( ?satyrMean > ?cacodaemonMean )
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT COUNT(?demon) AS ?count
WHERE {
  ?demon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> .
  ?demon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#beastCategoryName> "demon" .
  ?demon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#cmd> ?demonCmd .

  BIND(
    (SELECT AVG(?cmd)
     WHERE {
       ?beast a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> .
       ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#cmd> ?cmd .
     }) AS ?averageCmd
  )

  FILTER (?demonCmd > ?averageCmd)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT MIN(?flatFootedValue) WHERE {
