  ?languageEntry percentage ?percentage.

  # Ensure this is the maximum percentage in the country
  FILTER NOT EXISTS {
    ?otherLanguageEntry ref-countrycode ?country.
    ?otherLanguageEntry percentage ?otherPercentage.
    FILTER (?otherPercentage > ?percentage)
  }
}

